  add("Date format","തീയതി രീതി");add("Monthly statement (PDF)","മാസിക സ്റ്റേറ്റ്മെന്റ് (PDF)");add("Statement for","സ്റ്റേറ്റ്മെന്റ് ഏത് മാസത്തേത്");add("Share statement","സ്റ്റേറ്റ്മെന്റ് പങ്കിടുക");add("Statement could not be created","സ്റ്റേറ്റ്മെന്റ് ഉണ്ടാക്കാനായില്ല");add("Import entries from CSV","CSV-യിൽ നിന്ന് കണക്കുകൾ ചേർക്കുക");add("Import entries?","കണക്കുകൾ ചേർക്കണോ?");add("Import","ചേർക്കുക");add("That file could not be read","ആ ഫയൽ വായിക്കാനായില്ല");add("Choose a file","ഫയൽ തിരഞ്ഞെടുക്കുക");
  add("Share month summary","മാസത്തിന്റെ കുറിപ്പ് പങ്കിടുക");add("Duplicate","പകർപ്പ് ഉണ്ടാക്കുക");add("Edit person","വ്യക്തിയെ തിരുത്തുക");add("Phone (optional)","ഫോൺ (നിർബന്ധമില്ല)");add("Repeats","ആവർത്തനം");add("Weekly","ആഴ്ചതോറും");add("Monthly","മാസത്തോറും");add("Yearly","വർഷത്തോറും");add("From account","ഏത് അക്കൗണ്ടിൽ നിന്ന്");add("No category","വിഭാഗമില്ല");add("Pause","നിർത്തിവയ്ക്കുക");add("Resume","വീണ്ടും തുടങ്ങുക");
